sys_script_include.script:
var LicenseAPI = Class.create();
LicenseAPI.CONSTANTS = {
    INT_MAP: {
        GET: {
            path: "/apps/licensing/v1/product/${productId}/sku/${skuId}/user/${userId}",
            httpMethod: "GET",
            pathParams: ["productId", "skuId", "userId"],
            aliasId: "150209ddeb87ba105c06fcffcad0cd42"
        },
        INSERT: {
            path: "/apps/licensing/v1/product/${productId}/sku/${skuId}/user",
            httpMethod: "POST",
            pathParams: ["productId", "skuId"],
            content: {
                "userId": ""
            },
            aliasId: "150209ddeb87ba105c06fcffcad0cd42"
        },
        DELETE: {
            path: "/apps/licensing/v1/product/${productId}/sku/${skuId}/user/${userId}",
            httpMethod: "DELETE",
            pathParams: ["productId", "skuId", "userId"],
            aliasId: "150209ddeb87ba105c06fcffcad0cd42"
        },
        LIST_FOR_PRODUCT: {
            path: "/apps/licensing/v1/product/${productId}/users",
            httpMethod: "GET",
            pathParams: ["productId"],
            queryParams: ["customerId"],
            aliasId: "150209ddeb87ba105c06fcffcad0cd42"
        },
        LIST_FOR_PRODUCT_AND_SKU: {
            path: "/apps/licensing/v1/product/${productId}/sku/${skuId}/users",
            httpMethod: "GET",
            pathParams: ["productId", "skuId"],
            queryParams: ["customerId"],
            aliasId: "150209ddeb87ba105c06fcffcad0cd42"
        }
    }
};
LicenseAPI.prototype = {
    initialize: function() {},

    ensureToken: function() {
        const context = "x_neyu_rest_utils_oauth_credentials";
        const requestor = gs.getProperty("x_neyu_google_nyu.license.api.credential.id");
        (new global.OAuthTokenGetter()).processJWT(
            requestor,
            context,
            "8491b701ebcf7a105c06fcffcad0cda8", // Google Licensing API
            "3b683f45ebcf7a105c06fcffcad0cd99" // Google Licensing API default_profile
        );
    },

    get: function(productId, skuId, userId) {
        if (!productId || !skuId || !userId) {
            return {
                error: true,
                errorMessage: "There were missing parameters"
            };
        }

        this.ensureToken();

        const pathParams = {
            productId: productId,
            skuId: skuId,
            userId: userId
        };
        const config = LicenseAPI.CONSTANTS.INT_MAP.GET;
        const requestConfig = {
            ...config,
            pathParams
        };

        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        let response;
        try {
            response = api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error("[get] there was an internal error building and executing" +
                " the RestMessage.\nError: " + ex);
            return {
                error: true,
                errorMessage: ex + ""
            };
        }

        if (response.error) {
            gs.error("[get] There was an error returned from the Google API." +
                "\nError: " + response.errorMessage);
        }

        // gs.info("[get] Response: " + JSON.stringify(response));
        return {
            ...response,
            error: response.status != 200,
            errorMessage: (
                response.status != 200 ?
                response.responseBody : response.errorMessage
            )
        };
    },

    insert: function(productId, skuId, userId) {
        if (!productId || !skuId || !userId) {
            return {
                error: true,
                errorMessage: "There are missing parameters"
            };
        }

        this.ensureToken();

        const config = LicenseAPI.CONSTANTS.INT_MAP.INSERT;
        const content = {
            userId: userId
        };
		const pathParams = {
			productId: productId,
			skuId: skuId
		};
        const requestConfig = {
            ...config,
			pathParams,
            content: JSON.stringify(content)
        };

        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        let response;
        try {
            response = api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error("[insert] There wasn an error building and executing the " +
                " RESTMessage object.\nError: " + ex);
            return {
                error: true,
                errorMessage: ("There was an internal error when trying to contact Google." +
                    " Please contact your system administrator.")
            };
        }

        if (response.error) {
            gs.error("[insert] An error response was received from Google License API." +
                "\nResponse: " + JSON.stringify(response));
        }

        return {
            ...response,
            error: response.status != 201,
            errorMessage: (
                response.status != 201 ?
                response.responseBody : response.errorMessage
            )
        };
    },

    delete: function(productId, skuId, userId) {
        if (!productId || !skuId || !userId) {
            return {
                error: true,
                errorMessage: "There were missing parameters"
            };
        }

        this.ensureToken();

        const pathParams = {
            productId: productId,
            skuId: skuId,
            userId: userId
        };
        const config = LicenseAPI.CONSTANTS.INT_MAP.DELETE;
        const requestConfig = {
            ...config,
            pathParams
        };

        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        let response;
        try {
            response = api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error("[delete] there was an internal error building and executing" +
                " the RestMessage.\nError: " + ex);
            return {
                error: true,
                errorMessage: ex + ""
            };
        }

        if (response.error) {
            gs.error("[delete] There was an error returned from the Google API." +
                "\nError: " + response.errorMessage);
        }

        // gs.info("[get] Response: " + JSON.stringify(response));
        return {
            ...response,
            error: response.status != 200,
            errorMessage: (
                response.status != 200 ?
                response.responseBody : response.errorMessage
            )
        };
    },

    listForProduct: function(productId, customerId) {
        if (!productId || !customerId) {
            return {
                error: true,
                errorMessage: "There are missing required parameters"
            };
        }

        this.ensureToken();

        const pathParams = {
            productId: productId
        };
        const queryParams = {
            customerId: customerId
        };
        const config = LicenseAPI.CONSTANTS.INT_MAP.LIST_FOR_PRODUCT;
        const requestConfig = {
            ...config,
            pathParams,
            queryParams
        };

        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        let response;
        try {
            response = api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error("[listForProduct] There was an error building and executing " +
                " the RESTMessage.\nError: " + ex);
            return {
                error: true,
                errorMessage: "There was an internal error connecting to Google. Please contact your system administrator"
            };
        }

        if (response.error) {
            gs.error("[listForProduct] There wasn an error returned from google." +
                "\nResponse: " + JSON.stringify(response));
        }

        return {
            ...response,
            error: response.status != 200,
            errorMessage: (
                response.status != 200 ?
                response.responseBody : response.errorMessage
            )
        };
    },

    listForProductAndSku: function(productId, customerId, skuId) {
        if (!productId || !customerId || !skuId) {
            return {
                error: true,
                errorMessage: "There are missing required parameters"
            };
        }

        this.ensureToken();

        const pathParams = {
            productId: productId,
            skuId: skuId
        };
        const queryParams = {
            customerId: customerId
        };
        const config = LicenseAPI.CONSTANTS.INT_MAP.LIST_FOR_PRODUCT_AND_SKU;
        const requestConfig = {
            ...config,
            pathParams,
            queryParams
        };

        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        let response;
        try {
            response = api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error("[listForProductAndSku] There was an error building and executing " +
                " the RESTMessage.\nError: " + ex);
            return {
                error: true,
                errorMessage: "There was an internal error connecting to Google. Please contact your system administrator"
            };
        }

        if (response.error) {
            gs.error("[listForProductAndSku] There wasn an error returned from google." +
                "\nResponse: " + JSON.stringify(response));
        }

        return {
            ...response,
            error: response.status != 200,
            errorMessage: (
                response.status != 200 ?
                response.responseBody : response.errorMessage
            )
        };
    },

    type: 'LicenseAPI'
};
